INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HM', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Place value of digits up to hundreds of millions', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.a']::text[], 'Given a whole number up to 999,999,999 the child names the place of any digit (ones to hundred millions), including digits beside zeros, and says which digit sits in a named place. Numbers come from real settings such as a county budget or the number of phone lines.', '["name the place of a digit","which digit is in a named place","read a place value chart","how many places a number has"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.TOTAL_VALUE_HM', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Total value of digits up to hundreds of millions', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.a']::text[], 'Given a whole number up to 999,999,999 the child gives the total value of a chosen digit (digit times its place), adds the total values of two digits, and writes the number in expanded form. The child does not mistake a digit for its total value.', '["total value of an underlined digit","total values of two digits added","expanded form","difference between two digits of the same value"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SYMBOLS_HM', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Read and write numbers in symbols up to hundreds of millions', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.b']::text[], 'Given a number said or written in parts (for example 45 million, 12 thousand and 7) the child writes it in figures with every place filled and zero as a place holder, and reads a figure aloud in groups of three. Numbers up to 999,999,999.', '["write from parts","choose the number in figures","spot the missing zero","read a number aloud in groups"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.WORDS_FROM_FIGURES', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Write a number in words (figures to words), up to millions', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.c']::text[], 'The child writes a number up to 9,999,999 in words with British spelling, a hyphen in twenty-one to ninety-nine, and each group (millions, thousands, hundreds) in order. Zeros in a group are not spoken. The design limit for words is millions.', '["choose the words for a figure","write a cheque amount in words","spot the mistake in the words","say the same number two ways"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_NUMBERS_WORDS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.FIGURES_FROM_WORDS', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Write a number in figures from words, up to millions', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.c']::text[], 'Given a number in words up to millions, such as "two million and forty-five thousand and seven", the child writes it in figures with zero place holders in every empty place.', '["words to figures","which figures match these words","fill the missing zero","order two numbers given in words"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_NUMBERS_WORDS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_TO_PLACE', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Round whole numbers to the nearest ten up to hundred million', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.d']::text[], 'The child rounds a number up to 999,999,999 to the nearest ten, hundred, thousand, ten thousand, hundred thousand, million, ten million or hundred million: looks at the digit just to the right, rounds up on 5 or more, and writes zeros in all places after the one rounded.', '["round to a named place","which digit decides","round the same number two ways","choose the rounded number"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_ROUNDING_WHOLE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ROUND_IN_CONTEXT', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Round large numbers in news, budgets and populations', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.d']::text[], 'Given a real setting (a population, a county budget, a news report) the child chooses the sensible place to round to, rounds the number, and says why the rounded number is only an estimate. Rounding a carried digit (such as 999,500 to the nearest thousand) is included.', '["round the number in a report","which rounding is correct","why a rounded number is not exact","round and write in words"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_ROUNDING_WHOLE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.EVEN_ODD', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Classify whole numbers as even or odd', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.e']::text[], 'The child classifies any whole number up to millions as even or odd by its last digit, and knows that sums and products of even and odd numbers follow a pattern (even + even is even, odd + odd is even, even x anything is even).', '["even or odd","sort a list","even or odd after adding","is zero even"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G7_PRIMES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.PRIME_NUMBERS', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Identify prime and composite numbers up to 100', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.e']::text[], 'The child tells prime from composite numbers up to 100 by testing small divisors, knows that 1 is neither, that 2 is the only even prime, and that an odd number is not always prime. The child lists the primes up to 50.', '["is this number prime","pick the primes from a table","the only even prime","list primes between two numbers"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_PRIMES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ADD_SUB_LARGE', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Add and subtract large whole numbers (up to 9 digits)', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child adds and subtracts whole numbers of up to nine digits in a column, regrouping across zeros, and decides whether to add or subtract in a story about money, population or distance. Answers are checked by estimating.', '["add large amounts","subtract across zeros","sum or difference in a story","check with an estimate"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.MULT_LARGE', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Multiply large whole numbers (up to 3 digits by 3 digits)', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child multiplies a number of up to 4 digits by a number of up to 3 digits using long multiplication, with the zero place holder in the second and third rows, and by 10, 100 and 1,000 by shifting the digits. The product is checked by estimating.', '["long multiplication","multiply by 100","estimate to check","multiplication in a story"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.DIV_LARGE', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Divide large whole numbers (up to 6 digits by up to 3 digits)', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child divides a number of up to 6 digits by a number of up to 3 digits by long division, with zeros in the quotient where a digit does not fit, writes the remainder as a whole number, and checks by multiplying back.', '["long division","zero in the quotient","what the remainder means in a story","check by multiplying"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_BODMAS_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.ORDER_OF_OPERATIONS', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Work out combined operations in the correct order (with brackets)', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child works out expressions of up to three operations with brackets, working brackets first, then multiplication and division from left to right, then addition and subtraction from left to right. Numbers up to 3 digits.', '["work out the expression","which operation first","put in brackets to make a value","find the mistake in the order"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_BODMAS_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.OPERATIONS_IN_CONTEXT', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Use whole-number operations to solve real-life problems', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child reads a story with two or three steps (fares, fuel, rent, bags and rows), chooses the operations, works them in order and writes the answer with its unit. Money left, total takings and equal sharing are included.', '["two-step story","three-step story","which working is right","find the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_BODMAS_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_EXTEND_RULE', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Find the rule of a number sequence and extend it', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.g']::text[], 'Given the first four to six terms of a sequence with a constant difference or a constant multiplier, the child finds the rule, continues the sequence, and spots a term that does not fit.', '["next term","state the rule","the odd one out","increasing or decreasing sequence"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_NTH_TERM', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Find a term far along a number sequence', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.g']::text[], 'For a sequence that goes up or down by the same amount, the child finds a distant term (for example the 12th) by first term plus the number of steps times the difference, and does not count the first term as a step.', '["the 12th term","which term is this number","seats in row n","check with a table"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.WHOLE_NUMBERS.SEQ_CREATE_RULE', 'MATH.G7.NUMBER.WHOLE_NUMBERS', 'mathematics', 7, 'Create a number sequence from a rule', ARRAY['MATH.G7.NUMBER.WHOLE_NUMBERS.h']::text[], 'Given a rule such as "start at 5, add 4" or "multiply by 3 then add 3", the child writes the first terms, and makes a sequence of their own for a number game, checking that the terms follow the rule every time.', '["write the terms from a rule","terms of a two-step rule","make a puzzle sequence","check a classmate''s sequence"]'::jsonb, '["procedure","creating"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_2_4_8_5_10', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Test divisibility by 2, 4, 5, 8 and 10 from the last digits', ARRAY['MATH.G7.NUMBER.FACTORS.a']::text[], 'The child tests a number up to 6 digits for divisibility by 2, 5 and 10 from the last digit, by 4 from the last two digits and by 8 from the last three digits, and explains the test.', '["is it divisible by 4","which numbers pass the test","make the number divisible by 8","explain the test"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_DIVISIBILITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_3_6_9', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Test divisibility by 3, 6 and 9 with the sum of the digits', ARRAY['MATH.G7.NUMBER.FACTORS.a']::text[], 'The child adds the digits of a number up to 6 digits and tests the sum for 3 and 9, and knows a number is divisible by 6 only when it is even and divisible by 3.', '["divisible by 3 or 9","divisible by 6: count from a table","find the missing digit","spot the wrong test"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_DIVISIBILITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.DIV_BY_11', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Test divisibility by 11 with the alternating sum of digits', ARRAY['MATH.G7.NUMBER.FACTORS.a']::text[], 'The child adds the digits in the odd places and in the even places, subtracts the two sums, and says the number is divisible by 11 when the difference is 0 or a multiple of 11.', '["test a 4-digit number","spot the slip in the working","make a number divisible by 11","explain the test"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_DIVISIBILITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.PRIME_FACTORISE', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Write a composite number as a product of prime factors', ARRAY['MATH.G7.NUMBER.FACTORS.b']::text[], 'The child splits a number up to 500 with a factor tree or repeated division by 2, 3, 5, 7 and 11 until every factor is prime, writes repeated factors in full or with a power, and explains why a number with no small factors may still be composite.', '["factor tree","repeated division","find the mistake in the working","why 143 is not prime"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_PRIME_FACTORIZATION', 'G7_PRIMES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_BY_FACTORS', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Find the GCD of numbers by the factor method', ARRAY['MATH.G7.NUMBER.FACTORS.c']::text[], 'The child writes each of two or three numbers (up to 200) as a product of primes, multiplies the primes common to all of them, taking each as many times as it is in every number, and gets the GCD.', '["GCD of two numbers","GCD of three numbers","GCD or LCM","check by dividing"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_GCD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_BY_FACTORS', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Find the LCM of numbers by the factor method', ARRAY['MATH.G7.NUMBER.FACTORS.c']::text[], 'The child writes each of two or three numbers (up to 60) as a product of primes and multiplies each prime the greatest number of times it appears in any one number, and gets the LCM.', '["LCM of two numbers","LCM of three numbers","why the product is not the least","check with multiples"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_LCM']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.GCD_IN_CONTEXT', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Use the GCD to solve problems of cutting and packing', ARRAY['MATH.G7.NUMBER.FACTORS.d']::text[], 'The child decides from a story that the greatest equal size or number of equal groups is the GCD (cutting ropes, packing boxes, tiling) and works it out for two or three quantities, answering the size or the number asked.', '["longest equal pieces","greatest number of equal packs","which is the GCD story","what the GCD means here"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_GCD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FACTORS.LCM_IN_CONTEXT', 'MATH.G7.NUMBER.FACTORS', 'mathematics', 7, 'Use the LCM to solve problems of events that repeat together', ARRAY['MATH.G7.NUMBER.FACTORS.d']::text[], 'The child decides from a story that the first time two or three repeating events coincide is the LCM (matatus leaving, bells ringing) and works it out in minutes or days, answering the time asked.', '["when do they meet again","three bells","which is the LCM story","next time in clock time"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_LCM']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.COMPARE_FRACTIONS', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Compare and order fractions with different denominators', ARRAY['MATH.G7.NUMBER.FRACTIONS.a']::text[], 'The child compares two or three fractions with denominators up to 12 by renaming them with a common denominator, decides which is greater, orders them, and can explain why a bigger denominator does not mean a bigger fraction.', '["which is greater","order three fractions","choose the best reason","who has read the most"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_FRACTIONS_COMPARE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.ADD_UNLIKE_FRACTIONS', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Add fractions and mixed numbers with unlike denominators', ARRAY['MATH.G7.NUMBER.FRACTIONS.b']::text[], 'The child adds two fractions or mixed numbers with unlike denominators (up to 12) by renaming with the LCM, adds numerators, carries any whole from the fraction part, and writes the sum in simplest form.', '["add two fractions","add mixed numbers","a sum in a story","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_FRACTIONS_ADD_UNLIKE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.SUBTRACT_UNLIKE_FRACTIONS', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Subtract fractions and mixed numbers with unlike denominators', ARRAY['MATH.G7.NUMBER.FRACTIONS.c']::text[], 'The child subtracts fractions or mixed numbers with unlike denominators (up to 12) by renaming with the LCM, regroups a whole into the fraction part when needed, reduces the whole by one, and simplifies.', '["subtract two fractions","subtract mixed numbers with regrouping","what is left in a story","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_FRACTIONS_ADD_UNLIKE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_WHOLE', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Multiply a fraction by a whole number', ARRAY['MATH.G7.NUMBER.FRACTIONS.d']::text[], 'The child multiplies a fraction by a whole number (and finds a fraction of a quantity), multiplying the numerator and keeping the denominator, simplifies, and writes an improper result as a mixed number.', '["multiply a fraction by a whole number","fraction of an amount","repeated addition picture","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_FRACTIONS_MUL']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.MULT_FRACTION_BY_FRACTION', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Multiply fractions and mixed numbers', ARRAY['MATH.G7.NUMBER.FRACTIONS.d']::text[], 'The child multiplies a fraction by a fraction or a mixed number by writing mixed numbers as improper fractions, multiplying numerators and denominators, simplifying (also across before multiplying), and finds a fraction of a fraction of an amount in a story.', '["multiply two fractions","multiply a mixed number","part of a part","find the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_FRACTIONS_MUL']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.RECIPROCAL', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Find the reciprocal of a fraction, a whole number or a mixed number', ARRAY['MATH.G7.NUMBER.FRACTIONS.e']::text[], 'The child writes the reciprocal by turning a fraction upside down, writes a whole number as a fraction over 1 first, writes a mixed number as an improper fraction first, and checks that the number times its reciprocal is 1.', '["write the reciprocal","reciprocal of a mixed number","check by multiplying to 1","use a reciprocal in a story"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_RECIPROCALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_FRACTION_BY_WHOLE', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Divide a fraction by a whole number', ARRAY['MATH.G7.NUMBER.FRACTIONS.f']::text[], 'The child divides a fraction or a mixed number by a whole number by multiplying the denominator (or by the reciprocal), simplifies, and knows the result is smaller than the fraction.', '["divide a fraction by a whole number","share equally among drums","which working is right","check the size"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_FRACTIONS_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_BY_FRACTION', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Divide by a fraction or a mixed number', ARRAY['MATH.G7.NUMBER.FRACTIONS.f']::text[], 'The child divides a whole number, fraction or mixed number by a fraction or a mixed number by multiplying by the reciprocal of the divisor (the second number only), writing mixed numbers as improper fractions first.', '["divide a fraction by a fraction","divide a mixed number","which number is flipped","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_FRACTIONS_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.DIVIDE_WHOLE_BY_FRACTION', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Divide a whole number by a fraction and use it to count how many fit', ARRAY['MATH.G7.NUMBER.FRACTIONS.g']::text[], 'The child divides a whole number by a fraction, chooses division when the story asks how many small amounts fit into a large one (cups from a jug, bags from a sack), and knows the answer is larger than the whole number.', '["how many fit","which calculation","divide a whole number by a fraction","will the answer be larger or smaller"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_FRACTIONS_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_ADD_RULE', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Continue a fraction sequence that adds or takes away the same fraction', ARRAY['MATH.G7.NUMBER.FRACTIONS.h']::text[], 'The child finds the constant gap between terms of a sequence of fractions with a common denominator, keeps the denominator, and writes the next terms and a term that is a whole number as a fraction.', '["next term","the gap","a decreasing sequence","a whole number as a term"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES', 'G7_FRACTIONS_ADD_UNLIKE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_MULTIPLY_RULE', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Find the rule of a fraction sequence that multiplies or divides', ARRAY['MATH.G7.NUMBER.FRACTIONS.h']::text[], 'The child finds that terms such as 1, 1/3, 1/9 follow a constant ratio, states the rule (divide by 3, or multiply by 1/3), and continues the sequence.', '["name the rule","next term","getting smaller: which rule","spot the term that does not fit"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES', 'G7_FRACTIONS_ADD_UNLIKE', 'G7_FRACTIONS_MUL']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_IN_TABLE', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Use a fraction pattern in a table to answer how long it takes', ARRAY['MATH.G7.NUMBER.FRACTIONS.h']::text[], 'Given a table of the part of a task done after equal times (2, 4, 6 hours), the child finds the part done per step, and answers when the task is complete or how much is done at a later time, counting hours and not steps.', '["when is it full","part after n hours","fill the table","which row is missing"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES', 'G7_FRACTIONS_ADD_UNLIKE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.FRACTIONS.FRACTION_SEQ_CREATE', 'MATH.G7.NUMBER.FRACTIONS', 'mathematics', 7, 'Create a number sequence with fractions for a number game', ARRAY['MATH.G7.NUMBER.FRACTIONS.i']::text[], 'The child writes a sequence of fractions from a rule (add 1/4, or multiply by 1/2), keeps every term in line with the rule, and writes a rule for a puzzle sequence of their own that a partner can solve.', '["write the first terms from a rule","make a puzzle","check a classmate''s sequence","rule for given terms"]'::jsonb, '["procedure","creating"]'::jsonb, ARRAY['G7_NUMBER_SEQUENCES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_PLACE_AND_TOTAL_VALUE', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Place value and total value of digits in decimals up to thousandths', ARRAY['MATH.G7.NUMBER.DECIMALS.a']::text[], 'The child names the place of a digit after the point (tenths, hundredths, thousandths), gives its total value (the 7 in 4.073 is worth 0.07), and writes a decimal from a place value chart whose rows are not in order.', '["name the place","total value of a digit","write the number from a chart","which digit is in the place"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_DECIMAL_PV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_COUNT_TENTHS', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Count how many tenths or hundredths are in a decimal', ARRAY['MATH.G7.NUMBER.DECIMALS.a']::text[], 'The child says how many tenths (or hundredths) make a decimal such as 7.7 (77 tenths) by counting the whole ones as ten tenths each.', '["how many tenths","how many hundredths","write as tenths","whole ones as tenths"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_DECIMAL_PV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_WHOLE', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Multiply a decimal by a whole number', ARRAY['MATH.G7.NUMBER.DECIMALS.b']::text[], 'The child multiplies a decimal with up to three places by a whole number up to 100 by multiplying without the point and putting the point back with the same number of places, and decides if the answer is sensible.', '["multiply a decimal","cost of 3.5 kg","find the mistake with the point","estimate to check"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_DECIMALS_MUL', 'G6_DECIMALS_MUL']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.MULT_DEC_BY_DEC', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Multiply a decimal by a decimal', ARRAY['MATH.G7.NUMBER.DECIMALS.b']::text[], 'The child multiplies two decimals by multiplying without points and giving the product as many decimal places as both factors together, uses it for the area of a rectangle with decimal sides, and says when the product is smaller than a factor.', '["multiply two decimals","area of a garden","where does the point go","is the product bigger or smaller"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_DECIMALS_MUL']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_DEC_BY_WHOLE', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Divide a decimal or a whole number by a whole number to get a decimal', ARRAY['MATH.G7.NUMBER.DECIMALS.c']::text[], 'The child divides a decimal by a whole number, and a whole number by a whole number with a decimal quotient (12 / 8 = 1.5), by long division with the point in the quotient directly above the point in the dividend.', '["share equally","divide with a point","where is the point","check by multiplying"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_DECIMALS_DIV', 'G6_DECIMALS_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DIV_BY_DECIMAL', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Divide by a decimal', ARRAY['MATH.G7.NUMBER.DECIMALS.c']::text[], 'The child divides by a decimal by moving the point in both numbers the same number of places until the divisor is whole, uses it to count how many small amounts fit into a large one, and finds a price per kilogram.', '["how many pieces","price per kilogram","move the point in both","check by multiplying"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_DECIMALS_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.DECIMALS.DEC_DIVISION_SIZE', 'MATH.G7.NUMBER.DECIMALS', 'mathematics', 7, 'Decide whether dividing by a decimal gives a bigger or smaller answer', ARRAY['MATH.G7.NUMBER.DECIMALS.c']::text[], 'The child says that dividing by a number less than 1 makes the answer larger and dividing by a number greater than 1 makes it smaller, using how many lots fit, and does not move the point without a reason.', '["bigger or smaller","why is the answer bigger than 6","choose the best explanation","estimate the quotient"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G7_DECIMALS_DIV', 'G6_DECIMALS_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_WHOLE_NUMBER', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Find the square of a whole number', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.a']::text[], 'The child finds the square of a whole number up to 50, and of multiples of 10 (30 squared is 900), by multiplying the number by itself, and knows that squaring is not doubling.', '["square of a number","square of a multiple of ten","which is a perfect square","area of a square"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G7_SQUARES_EXT']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FRACTION', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Find the square of a fraction', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.a']::text[], 'The child squares a fraction by multiplying the numerator by itself and the denominator by itself, simplifies, and says why the answer is smaller than the fraction.', '["which fraction is the square","square a fraction","spot the mistake","is it smaller"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SQUARES_EXT']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_DECIMAL', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Find the square of a decimal and use it for the area of a square', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.a']::text[], 'The child squares a decimal such as 0.03 or 1.5 by multiplying without the point and giving the square twice as many decimal places, and uses it for the area of a square plot and for the area when the side is doubled.', '["square of a decimal","area of a square garden","where does the point go","area when the side doubles"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_SQUARES_EXT']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_WHOLE_NUMBER', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Find the square root of a perfect square', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.b']::text[], 'The child finds the square root of a perfect square up to 2,500 by finding the number that multiplied by itself gives it, checks by squaring, and knows the root of a sum is not the sum of the roots.', '["find the square root","check by squaring","which is a perfect square","the root of a sum"]'::jsonb, '["recall","procedure","reasoning"]'::jsonb, ARRAY['G7_SQUARE_ROOTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_FRACTION_DECIMAL', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Find the square root of a perfect-square fraction or decimal', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.b']::text[], 'The child finds the root of a fraction by taking the root of the numerator and of the denominator (9/16 gives 3/4), and of a decimal that is a perfect square (0.09 gives 0.3 and 1.44 gives 1.2) by halving the decimal places.', '["root of a fraction","root of a decimal","check by squaring","where does the point go"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SQUARE_ROOTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_IN_CONTEXT', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Use a square root to find the side of a square plot and what follows from it', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.b']::text[], 'The child takes the square root of the area of a square plot to find a side, then uses the side (for the distance round, or to compare plots), reading the question to know which is needed.', '["side from the area","fence round the plot","difference between two sides","which measure is asked for"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_SQUARE_ROOTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BY_ANCHORS', 'MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 7, 'Place the square root of a number between two whole numbers using perfect squares', ARRAY['MATH.G7.NUMBER.SQUARES_AND_SQUARE_ROOTS.b']::text[], 'The child finds the two perfect squares either side of a number (98 lies between 81 and 100) and so places its root between two whole numbers (between 9 and 10). The number is not itself a perfect square: this skill supports checking roots.', '["between which two whole numbers","which perfect squares are either side","estimate a root","check a root"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_SQUARE_ROOTS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RATE_FIXED', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 7, 'Form an expression for a charge made of a rate and a fixed amount', ARRAY['MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.a']::text[], 'From a table or story (delivery of n jerricans at sh 30 each plus sh 10), the child writes the expression rate x n + fixed, tests it with n = 1 and n = 2, and says what each part means.', '["choose the expression from a table","what does each part mean","write the charge for n items","test with values"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_EXPRESSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_EXPRESSION_RELATIONS', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 7, 'Form an expression for quantities related to one unknown', ARRAY['MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.a']::text[], 'Given one person is x years old, another is 2 years younger and another is 3 times as old, the child writes an expression for each and for their total, using brackets only when a whole group is taken.', '["expression for each person","total of three ages","the difference between two ages","which expression is right"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_EXPRESSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.FORM_FROM_STATEMENT', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 7, 'Form an expression from a simple algebraic statement in words', ARRAY['MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.b']::text[], 'The child turns words such as "3 more than x", "5 less than n", "twice y and then 4 more" and "a third of m" into expressions, keeping the order for "less than".', '["words to expression","expression to words","which statement matches","less than in the right order"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_EXPRESSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_LIKE_TERMS', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 7, 'Simplify an expression by collecting like terms', ARRAY['MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.c']::text[], 'The child collects the x terms and the number terms of an expression with up to three terms of each kind, keeps each sign, counts a plain x as 1x, and substitutes a value to check or to use.', '["collect like terms","perimeter of a plot","find a and b in ax + b","substitute x"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SIMPLIFY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.SIMPLIFY_WITH_BRACKETS', 'MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 7, 'Remove a bracket multiplied by a number and simplify', ARRAY['MATH.G7.ALGEBR.ALGEBRAIC_EXPRESSIONS.c']::text[], 'The child multiplies every term inside a bracket by the number outside, collects like terms, and does not join an x term with a number term.', '["expand the bracket","perimeter with a bracket","find the wrong step","is x + 8 the same as 8x"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_SIMPLIFY', 'G7_EXPRESSIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.FORM_EQUATION_FROM_STORY', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 7, 'Form a linear equation from a story', ARRAY['MATH.G7.ALGEBR.LINEAR_EQUATIONS.a']::text[], 'From a story with a price for each item, a fixed amount and a total (8 books and a geometry set, total sh 398) the child writes an equation such as 8x + 150 = 398, with the fixed amount added once and on the same side as the books.', '["choose the equation","what does each part mean","write the equation","which story matches the equation"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_EQUATIONS_FORM']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_TWO_STEP', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 7, 'Solve a two-step linear equation', ARRAY['MATH.G7.ALGEBR.LINEAR_EQUATIONS.b']::text[], 'The child solves equations like 6x + 6 = 78 and 3n + 3 = 45 by undoing the added or subtracted number first and then the multiplier, doing the same to both sides, and checks by putting the answer back.', '["solve and check","solve from a table of values","find the wrong step","which step first"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_EQUATIONS_SOLVE', 'G7_EQUATIONS_FORM', 'G6_SIMPLE_EQUATIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_BOTH_SIDES', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 7, 'Solve an equation with the unknown on both sides', ARRAY['MATH.G7.ALGEBR.LINEAR_EQUATIONS.b']::text[], 'The child solves equations like 4x - 4 = 2x + 12 by taking the smaller x term from both sides, then undoing the number, then dividing, and checks in both sides.', '["solve with x on both sides","find the wrong step","what to do first","check in both sides"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_EQUATIONS_SOLVE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.EQUATION_BALANCE_REASON', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 7, 'Say why the same is done to both sides of an equation', ARRAY['MATH.G7.ALGEBR.LINEAR_EQUATIONS.b']::text[], 'The child explains that an equation is a balance, so what is done to one side must be done to the other, and that the unknown can be on either side.', '["why both sides","which explanation is right","balance picture","what stays the same"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G6_SIMPLE_EQUATIONS', 'G7_EQUATIONS_SOLVE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.ALGEBR.LINEAR_EQUATIONS.SOLVE_IN_CONTEXT', 'MATH.G7.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 7, 'Form and solve an equation to answer a question in a story', ARRAY['MATH.G7.ALGEBR.LINEAR_EQUATIONS.c']::text[], 'The child forms an equation for a story (ages after some years, a parking charge with a fixed part, equal boxes and loose items, money left after spending), solves it, and answers the quantity the question asks for, not the unknown.', '["ages in 4 years","parking charge","mangoes in boxes","money at the start","which quantity is asked"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_EQUATIONS_FORM', 'G7_EQUATIONS_SOLVE', 'G6_SIMPLE_EQUATIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.RIGHT_TRIANGLE_SIDES', 'MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP', 'mathematics', 7, 'Name the sides of a right-angled triangle', ARRAY['MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.a']::text[], 'The child finds the right angle in a triangle labelled with letters, names the hypotenuse as the side opposite the right angle (and the longest side), and names the other two sides as the legs.', '["which side is the hypotenuse","which is the longest side","name the legs","draw a right-angled triangle"]'::jsonb, '["recall"]'::jsonb, ARRAY['G7_PYTHAGORAS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.PYTHAGORAS_TEST', 'MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP', 'mathematics', 7, 'Test whether a triangle is right-angled using the squares of its sides', ARRAY['MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.b']::text[], 'The child squares the two shorter sides, adds them, and compares with the square of the longest side (exactly equal means a right angle), and explains why a 3, 4, 5 or 5, 12, 13 corner is square.', '["which triangle is right-angled","is this corner square","why does 5, 12, 13 show a right angle","find the mistake in the test"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_PYTHAGORAS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.FIND_HYPOTENUSE', 'MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP', 'mathematics', 7, 'Find the hypotenuse of a right-angled triangle', ARRAY['MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.b', 'MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.c']::text[], 'The child squares the two shorter sides, adds them and takes the square root to find the hypotenuse, and uses it for a brace on a gate, a wire from a pole to a peg and a diagonal path.', '["length of the brace","length of the wire","cost of a wire","which working is right"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_PYTHAGORAS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.FIND_SHORT_SIDE', 'MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP', 'mathematics', 7, 'Find a shorter side of a right-angled triangle', ARRAY['MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.b']::text[], 'The child subtracts the square of the known shorter side from the square of the hypotenuse and takes the square root, and knows a square root is not halving.', '["find the third side","find the wrong step","which operation first","check by squaring"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_PYTHAGORAS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.PYTHAGORAS_SAVING', 'MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP', 'mathematics', 7, 'Use the relationship to compare a straight path with a path along two sides', ARRAY['MATH.G7.MEASUR.PYTHAGOREAN_RELATIONSHIP.c']::text[], 'The child finds the straight path as the hypotenuse, adds the two sides for the long way, and subtracts to find how much shorter the straight path is, answering the quantity the question asks for.', '["how much shorter","length of the straight path","length along two sides","which quantity is asked"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_PYTHAGORAS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.CONVERT_LENGTH_UNITS', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Convert between cm, dm, m, Dm and Hm', ARRAY['MATH.G7.MEASUR.LENGTH.a']::text[], 'The child changes a length between cm, dm, m, Dm and Hm by multiplying when going to a smaller unit and dividing when going to a bigger one, using the number of small units in one big unit (1 m = 10 dm = 100 cm; 1 Hm = 100 m), also in two stages.', '["change metres to decimetres","two-stage conversion","why multiply or divide","find the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_LENGTH_CONV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.COMPARE_LENGTHS_UNITS', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Compare lengths given in different units', ARRAY['MATH.G7.MEASUR.LENGTH.a', 'MATH.G7.MEASUR.LENGTH.b']::text[], 'The child reads the size of each unit from a table, changes both lengths to the same unit, and finds how much longer one is, answering in the unit asked.', '["how much longer","which is longer","use the table of units","same unit first"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_LENGTH_CONV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.OPERATIONS_ON_LENGTH', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Add, subtract, multiply and divide lengths in different units in a story', ARRAY['MATH.G7.MEASUR.LENGTH.b']::text[], 'The child works with lengths in a story (rope cut into pieces, posts along a fence): changes to one unit, finds the total of several pieces, subtracts what is left, and counts posts on a straight fence as gaps plus one.', '["rope left after cutting","posts along a straight fence","which unit is the answer in","find the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_LENGTH_CONV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.PERIMETER_PLANE_FIGURES', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Find the perimeter of rectangles and L-shapes and use it for fencing', ARRAY['MATH.G7.MEASUR.LENGTH.c']::text[], 'The child finds the distance round a rectangle as 2 x (length + width), round an L-shape by adding every edge, compares plots by perimeter and not by area, and counts posts round a closed plot as distance divided by gap.', '["perimeter of an L-shape","which plot needs the longest fence","posts round a plot","fence or area"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_PERIMETER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.CIRCUMFERENCE_DISTANCE', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Find the circumference of a circle and use it for distance travelled and a track', ARRAY['MATH.G7.MEASUR.LENGTH.d']::text[], 'The child finds the circumference as pi x diameter (22/7 or 3.14 as the question says), uses it for the distance a wheel travels in many turns (changing cm to m), and for a track made of straight sides and half circles.', '["distance of a wheel","length of a running track","cm to m","half circles make a circle"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_CIRCUMFERENCE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.CIRCUMFERENCE_FIND_DIAMETER', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Find the diameter or radius of a circle from its circumference', ARRAY['MATH.G7.MEASUR.LENGTH.d']::text[], 'Given the distance round a circle, the child divides by pi (multiplies by 7/22) to find the diameter, halves it for the radius, and checks by multiplying back.', '["diameter from the distance round","radius from the circumference","check by multiplying","which one is asked"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_CIRCUMFERENCE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.LENGTH.CIRCUMFERENCE_REASON', 'MATH.G7.MEASUR.LENGTH', 'mathematics', 7, 'Reason about how the circumference changes with the diameter', ARRAY['MATH.G7.MEASUR.LENGTH.d']::text[], 'The child says the circumference is always about 3.14 times the diameter, so doubling the diameter doubles the circumference, and finds the pattern in a table of measured circles.', '["when the diameter doubles","find pi from a table","which statement is right","predict the distance round"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G7_CIRCUMFERENCE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.VOLUME_AND_CAPACITY.CUBIC_UNIT_CONVERT', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY', 'mathematics', 7, 'Know the cubic metre and change between m3 and cm3', ARRAY['MATH.G7.MEASUR.VOLUME_AND_CAPACITY.a', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY.b']::text[], 'The child says a cubic metre is a cube 100 cm by 100 cm by 100 cm (1,000,000 cm3), changes m3 to cm3 and back, and says why the three lengths are multiplied and not added.', '["m3 to cm3","cm3 to m3","why 1,000,000","blocks that make a cubic metre","find the mistake"]'::jsonb, '["recall","procedure","reasoning"]'::jsonb, ARRAY['G7_VOLUME_CUBOID']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.VOLUME_AND_CAPACITY.VOLUME_CUBOID_CUBE', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY', 'mathematics', 7, 'Work out the volume of cuboids and cubes and use it to count, find an edge or a height', ARRAY['MATH.G7.MEASUR.VOLUME_AND_CAPACITY.c']::text[], 'The child finds the volume of a cuboid or cube from its edges, finds the edge of a cube from the total length of its wire (12 edges), counts blocks that pack a carton exactly, and finds a missing height by dividing the volume by the base area.', '["volume of a cube from its wire","how many cubes pack a carton","find the height","volume of a tank"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_VOLUME_CUBOID', 'G6_VOLUME_CUBOID']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.VOLUME_AND_CAPACITY.VOLUME_CYLINDER', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY', 'mathematics', 7, 'Work out the volume of a cylinder', ARRAY['MATH.G7.MEASUR.VOLUME_AND_CAPACITY.c', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY.d']::text[], 'The child finds the radius from the diameter, the base area (pi x radius x radius), multiplies by the height for the volume, and works backwards to a height from the volume, and to litres.', '["volume from a diameter","height from the volume","volume then litres","base area step"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_VOLUME_CYLINDER']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.VOLUME_AND_CAPACITY.VOLUME_TO_LITRES', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY', 'mathematics', 7, 'Change a volume in cubic metres or cubic centimetres to litres', ARRAY['MATH.G7.MEASUR.VOLUME_AND_CAPACITY.d', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY.e']::text[], 'The child changes m3 to litres (x 1,000) and cm3 to litres (divide by 1,000), and states the relation between cm3, ml and litres.', '["litres in a tank","cm3 to litres","which unit is asked","one litre is how many cm3"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_VOLUME_CUBOID']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.VOLUME_AND_CAPACITY.CAPACITY_HOW_MANY', 'MATH.G7.MEASUR.VOLUME_AND_CAPACITY', 'mathematics', 7, 'Work out how many containers, cups or days a quantity of water lasts', ARRAY['MATH.G7.MEASUR.VOLUME_AND_CAPACITY.f']::text[], 'The child changes the quantity and the container to the same unit, then divides to find how many jerricans fill a tank, how many cups come from a can, or how many days a tank lasts from the total daily use.', '["jerricans to fill a tank","cups from a can","days of water","same unit first"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_VOLUME_CUBOID']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.TIME_UNITS_CONVERT', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Convert between seconds, minutes and hours', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.a', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.b']::text[], 'The child changes seconds to minutes and hours (60 and 3,600) and back, writes a time such as 8,400 seconds as hours and minutes (2 h 20 min), and never treats an hour as 100 minutes.', '["seconds to hours and minutes","minutes to hours","whole hours and minutes left","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.TIMETABLE_DURATION', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Find the time a vehicle is moving from a 24-hour timetable', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.a', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.b']::text[], 'The child reads a timetable on the 24-hour clock, finds the time of each leg, leaves out the waiting time at a stop, and gives the moving time in minutes.', '["moving time from a timetable","waiting time","length of one leg","whole journey including the stop"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.DISTANCE_UNITS_CONVERT', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Convert and combine distances in metres and kilometres', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.c']::text[], 'The child changes metres to kilometres (divide by 1,000) and back, finds a total distance such as laps or a return trip over several days, and answers in the unit asked.', '["laps in kilometres","to and from school for a week","both ways","answer in the right unit"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.SPEED_FROM_DISTANCE_TIME', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Work out speed in km/h from a distance and a time in hours and minutes', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.d', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.e']::text[], 'The child changes the time to hours (75 min is 1.25 h, with minutes out of 60), divides the distance by it, and does not multiply or invert; a timetable gives the time between two 24-hour readings.', '["speed of a matatu","speed from a timetable","minutes to hours","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.TIME_FROM_SPEED', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Work out the time of a journey from the distance and the speed', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.d', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.e']::text[], 'The child finds time as distance divided by speed, and changes a decimal number of hours to minutes by multiplying the decimal part by 60 (2.5 h = 150 min).', '["time in hours","time in minutes","decimal hours to minutes","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.AVERAGE_SPEED_TWO_LEGS', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Work out the average speed over two parts of a journey', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.e']::text[], 'The child finds the time of each part (distance divided by speed), adds them, and divides the total distance by the total time; the slower part takes longer, so the average is not halfway between the speeds.', '["time of each part","average speed","why not the middle","total time"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.SPEED_UNITS_CONVERT', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Convert speed between km/h and m/s', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.f']::text[], 'The child changes km/h to m/s by multiplying by 1,000 and dividing by 3,600 (divide by 3.6), and m/s to km/h by multiplying by 3.6, and explains why an hour has 3,600 seconds.', '["km/h to m/s","m/s to km/h","why divide by 3,600","find speed in m/s from metres and seconds"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.SPEED_COMPARE_MIXED_UNITS', 'MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED', 'mathematics', 7, 'Compare speeds given in different units', ARRAY['MATH.G7.MEASUR.TIME_DISTANCE_AND_SPEED.f']::text[], 'The child changes all speeds to km/h (or all to m/s) before saying which is fastest, and does not compare a number in m/s with a number in km/h.', '["which is fastest","order three speeds","same unit first","change m/s to km/h"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_SPEED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TEMPERATURE.TEMP_WORDS', 'MATH.G7.MEASUR.TEMPERATURE', 'mathematics', 7, 'Describe a temperature as cold, cool, warm or hot using a table of ranges', ARRAY['MATH.G7.MEASUR.TEMPERATURE.a']::text[], 'The child reads a table of temperature ranges and says whether a reading in degrees Celsius is cold, cool, warm or hot, and gives a sensible temperature for a day described in words.', '["which word for 35 degrees","a reading for a hot day","which range","order the words"]'::jsonb, '["recall"]'::jsonb, ARRAY['G7_TEMPERATURE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TEMPERATURE.TEMP_COMPARE_DIFFERENCE', 'MATH.G7.MEASUR.TEMPERATURE', 'mathematics', 7, 'Compare temperatures and find the difference, including readings below zero', ARRAY['MATH.G7.MEASUR.TEMPERATURE.b']::text[], 'The child says which of two places is hotter, warmer or colder, finds the difference between two readings (counting through zero when one is below it), and the difference between the highest and lowest points of a graph.', '["how much warmer","range of a graph","one below zero","which is colder"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_TEMPERATURE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TEMPERATURE.TEMP_UNITS', 'MATH.G7.MEASUR.TEMPERATURE', 'mathematics', 7, 'Know the Celsius and Kelvin scales', ARRAY['MATH.G7.MEASUR.TEMPERATURE.c']::text[], 'The child names degree Celsius and kelvin as units, knows water freezes at 0 degrees Celsius (273 K) and boils at 100 degrees Celsius (373 K), writes kelvin without a degree sign, and knows a Kelvin reading is larger than the Celsius reading.', '["freezing and boiling points","which unit","write the unit","which is bigger"]'::jsonb, '["recall"]'::jsonb, ARRAY['G7_TEMPERATURE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TEMPERATURE.TEMP_CONVERT_C_K', 'MATH.G7.MEASUR.TEMPERATURE', 'mathematics', 7, 'Convert between degrees Celsius and kelvin and compare readings in both', ARRAY['MATH.G7.MEASUR.TEMPERATURE.d']::text[], 'The child adds 273 to change degrees Celsius to kelvin and subtracts 273 for the reverse, knows a change in temperature is the same in both units, and puts both on one scale before comparing.', '["Celsius to kelvin","kelvin to Celsius","the hottest of three readings","a fall of temperature in kelvin","find the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_TEMPERATURE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.MEASUR.TEMPERATURE.TEMP_RISES_FALLS', 'MATH.G7.MEASUR.TEMPERATURE', 'mathematics', 7, 'Work out a temperature after a rise and a fall', ARRAY['MATH.G7.MEASUR.TEMPERATURE.e']::text[], 'The child starts from the first reading, adds each rise and subtracts each fall in turn, and gives the final temperature in degrees Celsius or kelvin.', '["reading at midnight","after two changes","what was the start","rise then fall"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_TEMPERATURE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.MEASURE_ANGLES_PROTRACTOR', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 7, 'Measure an angle with a protractor', ARRAY['MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.a']::text[], 'The child places the centre of the protractor on the corner and the base line along one arm, reads the scale that starts at zero on that arm, and states whether the angle is acute, right, obtuse or reflex.', '["read the angle","which scale","acute or obtuse","estimate then measure"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_ANGLES', 'G7_ANGLE_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 7, 'Bisect an angle with compasses and explain the steps', ARRAY['MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.b']::text[], 'The child bisects an angle with a ruler and compasses (arc across both arms from the corner, two equal arcs from those marks, line through the crossing point), says each half is half the original, and gives the reason for each arc.', '["size of each half","why this arc","order of the steps","which step is wrong"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_CONSTRUCTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 7, 'Plan the construction of 90, 60, 45, 30 and multiples of 7.5 degrees', ARRAY['MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.c']::text[], 'The child plans which angles to construct and how often to bisect to get 90, 60, 45, 30, 15 and 7.5 degrees, and builds angles such as 135 or 105 by adding or subtracting these.', '["how to make 30 degrees","plan for 135 degrees","which bisection gives 15","find the mistake in the plan"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_ANGLE_CONSTRUCTION', 'G7_CONSTRUCTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_TRIANGLES', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 7, 'Decide whether a triangle can be constructed and plan its construction', ARRAY['MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.d']::text[], 'The child decides whether three side lengths make a triangle (the two shorter sides together must be longer than the longest), and plans the construction of a triangle from its sides or from two sides and the angle between them.', '["can this triangle be drawn","which sides make a triangle","order of the steps","why the arcs do not meet"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G7_CONSTRUCTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_CIRCLES', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 7, 'Construct a circle of a given radius or diameter', ARRAY['MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.e']::text[], 'The child sets the compasses to the radius (half the diameter), places the point at the centre, and draws a circle, and says that every point on it is the same distance from the centre.', '["set the compasses","radius from diameter","why the point stays still","draw a circle of diameter 6 cm"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G7_CONSTRUCTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
