INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE.M_ARC_REASON_FOR_FIRST_ARC', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE', 'Gives the reason for the first arc as the reason for another step.', '{"question":"Why keep the compasses at the same width for the crossing arcs?","wrong_answer":"so the two marks on the arms are the same distance from the corner","correct_answer":"so the crossing point is the same distance from each mark"}'::jsonb, 'Mixes up steps.', 'The answer so the two marks on the arms are the same distance from the corner as a wrong option, with a reason that names the idea.', 'Each step has its own reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE.M_ARC_REASON_FOR_CROSSING_STEP', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE', 'Gives the reason for the crossing arcs as the reason for the first arc.', '{"question":"Why put the compass point on the corner for the first arc?","wrong_answer":"so the crossing point is the same distance from each mark","correct_answer":"so the two marks on the arms are the same distance from the corner"}'::jsonb, 'Mixes up steps.', 'The answer so the crossing point is the same distance from each mark as a wrong option, with a reason that names the idea.', 'The first arc makes two marks the same distance from the corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE.M_ARC_REASON_FOR_BISECTOR_STEP', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE', 'Gives the reason for the bisector line as the reason for the first arc.', '{"question":"Why put the compass point on the corner for the first arc?","wrong_answer":"that point is equally far from both arms","correct_answer":"so the two marks on the arms are the same distance from the corner"}'::jsonb, 'Mixes up steps.', 'The answer that point is equally far from both arms as a wrong option, with a reason that names the idea.', 'The line comes last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE.M_ARC_REASON_ARCS_TOO_SHORT', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.BISECT_ANGLE', 'Says the arcs are drawn so that they are long enough to meet.', '{"question":"Why put the compass point on the corner for the first arc?","wrong_answer":"otherwise the arcs would be too short to meet","correct_answer":"so the two marks are the same distance from the corner"}'::jsonb, 'Thinks the reason is only practical.', 'The answer otherwise the arcs would be too short to meet as a wrong option, with a reason that names the idea.', 'The point is the equal distance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES.M_BISECTED_TOO_FAR', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES', 'Bisects one time too many.', '{"question":"How do you make 30 degrees with ruler and compasses?","wrong_answer":"construct 60, bisect it, then bisect again (15)","correct_answer":"construct 60 and bisect it once"}'::jsonb, 'Bisects again to be careful.', 'The answer construct 60, bisect it, then bisect again (15) as a wrong option, with a reason that names the idea.', 'Each bisection halves: 60, 30, 15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES.M_WRONG_START_ANGLE', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES', 'Starts from 90 degrees to make 30 degrees.', '{"question":"How do you make 30 degrees?","wrong_answer":"construct 90 and bisect it (45)","correct_answer":"construct 60 and bisect it"}'::jsonb, 'Chooses the angle that is easiest to draw.', 'The answer construct 90 and bisect it (45) as a wrong option, with a reason that names the idea.', 'Bisecting 90 gives 45, not 30.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
