INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES.M_BISECTED_ONCE_ONLY', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_STANDARD_ANGLES', 'Bisects once and stops when a smaller angle is needed.', '{"question":"How do you make 15 degrees?","wrong_answer":"construct 60 and bisect it once (30)","correct_answer":"construct 60 and bisect it twice"}'::jsonb, 'Stops after the first bisection.', 'The answer construct 60 and bisect it once (30) as a wrong option, with a reason that names the idea.', 'Bisect again: 60, 30, 15.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
