INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_TRIANGLES.M_ANY_THREE_LENGTHS_MAKE_TRIANGLE', 'MATH.G7.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_TRIANGLES', 'Believes any three lengths make a triangle.', '{"question":"Sides 4, 3 and 10 cm: a triangle?","wrong_answer":"yes","correct_answer":"no: 3 + 4 is less than 10"}'::jsonb, 'Has only seen triangles that work.', 'The answer yes as a wrong option, with a reason that names the idea.', 'The two short sides must be longer than the long side or the arcs never meet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
